 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    rows = [[i for i in range(h) if grid[i][0] == 8]]
    # Separator lines span the full grid; derive the non-separator cell bands.
    row_bands, start = [], 0
    for i in range(h):
        if all(v == 8 for v in grid[i]):
            if start < i:
                row_bands.append((start, i))
            start = i + 1
    if start < h:
        row_bands.append((start, h))
    col_bands, start = [], 0
    for j in range(w):
        if all(grid[i][j] == 8 for i in range(h)):
            if start < j:
                col_bands.append((start, j))
            start = j + 1
    if start < w:
        col_bands.append((start, w))

    markers = {}
    for ri, (r0, r1) in enumerate(row_bands):
        for ci, (c0, c1) in enumerate(col_bands):
            colors = {grid[r][c] for r in range(r0, r1) for c in range(c0, c1) if grid[r][c] not in (0, 8)}
            if colors:
                markers[(ri, ci)] = next(iter(colors))

    painted = {}
    points = list(markers.items())
    for a in range(len(points)):
        (r1, c1), color = points[a]
        for b in range(a + 1, len(points)):
            (r2, c2), color2 = points[b]
            if color != color2:
                continue
            if r1 == r2:
                for c in range(min(c1, c2), max(c1, c2) + 1):
                    painted[(r1, c)] = color
            elif c1 == c2:
                for r in range(min(r1, r2), max(r1, r2) + 1):
                    painted[(r, c1)] = color

    out = [row[:] for row in grid]
    for (ri, ci), color in painted.items():
        r0, r1 = row_bands[ri]
        c0, c1 = col_bands[ci]
        for r in range(r0, r1):
            for c in range(c0, c1):
                old = out[r][c]
                out[r][c] = color if old in (0, color) else (6 if {old, color} == {2, 3} else color)
    return out
